// zsc
fn rename(todos: Array<Todo>, id: i32, d: Draft) -> Result<Array<Todo>, FormError> {
  let old = find(todos, id) |> .ok_or(NotFound { id })?;   // pipe: ok_or を脱糖した後に ? が付く
  let ok = check(old) && validate(d, id)?.done;
  //                    ^ error: `?` on the right of `&&` would run even when the left is false here:
  //                      bind it first (`let t = validate(d, id)?;`)
  Ok(todos |> .map((x) => if x.id == id { { ...old, done: true } } else { x }))
}

